+#pragma once
+// Linux buffered reads populate the same page cache as the model mmap.
+#include <algorithm>
+#include <atomic>
+#include <cstdio>
+#include <sys/resource.h>
+#ifndef MADV_POPULATE_READ
+#define MADV_POPULATE_READ 22
